using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedKnowledgeEffect", menuName = "Data/Battle/Effects/Enemy/CorruptedKnowledge Effect")]
public class CorruptedKnowledgeEffect : Effect
{
	[Header("Purify and Corrupt Actions")]
	[SerializeField]
	private CorruptAction areaCorruptAction;

	public bool DiceHaveCorruptNotAreaCorruptAction(Dice dice)
	{
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			BattleAction battleAction = dice.GetDiceFaces()[i].BattleAction;
			if (battleAction is CorruptAction && !battleAction.name.Contains("AreaCorrupt"))
			{
				return true;
			}
			if (dice.GetDiceFaces()[i].EnableSecondAction && dice.GetDiceFaces()[i].SecondBattleAction is CorruptAction && !battleAction.name.Contains("AreaCorrupt"))
			{
				return true;
			}
		}
		return false;
	}

	public Dice TransformIntoAreaCorruptAction(Dice dice)
	{
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			BattleAction battleAction = dice.GetDiceFaces()[i].BattleAction;
			if (battleAction is CorruptAction && !battleAction.name.Contains("AreaCorrupt"))
			{
				dice.GetDiceFaces()[i].BattleAction = areaCorruptAction;
				dice.GetDiceFaces()[i].ActionValue = 1;
			}
			if (dice.GetDiceFaces()[i].EnableSecondAction)
			{
				BattleAction secondBattleAction = dice.GetDiceFaces()[i].SecondBattleAction;
				if (secondBattleAction is CorruptAction && !secondBattleAction.name.Contains("AreaCorrupt"))
				{
					dice.GetDiceFaces()[i].SecondBattleAction = areaCorruptAction;
					dice.GetDiceFaces()[i].SecondActionValue = 1;
				}
			}
		}
		return dice;
	}
}
